import React from 'react';

const API_URL = process.env.REACT_APP_API_URL;

export function BookCard() {
  return <img src={`${API_URL}/covers/default.jpg`} />;
}

import React from 'react';

export function BookCard() {
  const debug = import.meta.env.VITE_DEBUG === 'true';
  return <div data-debug={debug}>Card</div>;
}

const BASE = process.env.API_BASE_URL ?? 'http://localhost:3000';

export async function fetchBooks() {
  return fetch(`${BASE}/books`).then(r => r.json());
}

const LOG_LEVEL = import.meta.env.VITE_LOG_LEVEL ?? 'info';

export function log(msg: string) {
  if (LOG_LEVEL === 'debug') console.debug(msg);
}

const BASE_URL = process.env.API_URL;
const TIMEOUT = Number(process.env.API_TIMEOUT ?? '5000');
const API_KEY = process.env.API_KEY;

export function createClient() {
  return { baseUrl: BASE_URL, timeout: TIMEOUT, apiKey: API_KEY };
}

export const config = {
  apiUrl: process.env.API_BASE_URL ?? 'http://localhost:3000',
  debug: process.env.NODE_ENV === 'development',
  logLevel: process.env.LOG_LEVEL ?? 'info',
};

export const config = {
  apiUrl: import.meta.env.VITE_API_URL ?? '/api',
  debug: import.meta.env.DEV,
};

export const env = {
  apiUrl: import.meta.env.VITE_API_URL,
  mode: import.meta.env.MODE,
} as const;

/// <reference types="vite/client" />

interface ImportMetaEnv {
  readonly VITE_API_URL: string;
  readonly VITE_DEBUG: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

// Old: const url = process.env.API_URL;
// Now using config:
import { config } from '../config';

export async function fetchBooks() {
  return fetch(`${config.apiUrl}/books`).then(r => r.json());
}

import { config } from '../config';

test('reads env', () => {
  process.env.API_URL = 'http://test';
  expect(config.apiUrl).toBe('http://test');
});

import { config } from './config';

export function loadConfig() {
  // Validates config from import.meta.env.VITE_API_URL
  const raw = import.meta.env.VITE_EXTRA_CONFIG;
  return { ...config, extra: raw };
}
